class OrderFacade {                                  // coarse use-case boundary
public:
    OrderFacade(InventoryService& inv, PricingService& pricing, OrderRepository& repo)
        : inv_(inv), pricing_(pricing), repo_(repo) {}
    OrderId place_order(const PlaceOrderRequest& req) {
        auto quote = pricing_.quote(req.sku, req.qty);
        inv_.reserve(req.sku, req.qty);
        return repo_.insert(Order{req.customer_id, quote});   // one unit of work
    }
private:
    InventoryService& inv_; PricingService& pricing_; OrderRepository& repo_;
};
